import java.sql.*;import java.nio.file.*;import java.util.*;import java.lang.management.*;import com.alibaba.fastjson2.*;import webridge.wbridge.storedprocedure.SPConfig;import webridge.wbridge.storedprocedure.invocation.SPInvokeManager;
public class GuardSetTiming {
 static boolean optimized,active,hit;static JSONObject in;static String api;
 static long questions(Connection c)throws Exception{try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SHOW SESSION STATUS LIKE 'Questions'")){r.next();return r.getLong(2);}}
 static Map<String,Long>status(Connection c)throws Exception{Map<String,Long>m=new TreeMap<>();try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SHOW SESSION STATUS WHERE Variable_name IN('Questions','Queries','Com_call_procedure','Com_select','Com_begin','Com_commit')")){while(r.next())m.put(r.getString(1),r.getLong(2));}return m;}
 static void execute(String[]a)throws Exception{Path data=Paths.get(a[0]),home=Paths.get(a[1]),out=Paths.get(a[2]);Files.createDirectory(out);Path guard=Paths.get(System.getProperty("snb.watchdogDir",out.toString()));JSONArray all=JSON.parseArray(new String(Files.readAllBytes(data.resolve("inputs.json")),"UTF-8"));in=all.getJSONObject(0);api=JSON.parseObject(new String(Files.readAllBytes(home.resolve("metadata.json")),"UTF-8")).getString("api");int warm=Integer.parseInt(a[3]),measure=Integer.parseInt(a[4]);SPConfig.addConfig(home.resolve("aligned.conf").toFile());System.setProperty("spDefDir",home.resolve("generated/sql").toString());SnbSetSql.configure(data);
 SnbSetSql.regionBoundary=new SnbSetSql.RegionBoundary(){public void enter(Connection c)throws Exception{if(optimized){SPInvokeManager.beginApi(api);active=true;SPInvokeManager.setInvokingSp(true);for(String k:in.keySet()){if(k.equals("expected"))continue;Object v=in.get(k);SPInvokeManager.storeParam("REQUEST_PARAM_"+k,v);if(v instanceof String)SPInvokeManager.storeParam("M_L_String__REQUEST_PARAM_"+k,v);if(v instanceof Long)SPInvokeManager.storeParam("M_J_field_REQUEST_PARAM_"+k+"_java_lang_Long_value",v);}}}public void leave(Connection c)throws Exception{if(active){hit=SPInvokeManager.isInvokingSp();SPInvokeManager.endApi();active=false;}}};
 ThreadMXBean cpu=ManagementFactory.getThreadMXBean();if(cpu.isCurrentThreadCpuTimeSupported()&&!cpu.isThreadCpuTimeEnabled())cpu.setThreadCpuTimeEnabled(true);
 try(Connection c=DriverManager.getConnection(SnbSetSql.url,"root","")){Files.write(guard.resolve("connection-id.json"),("{\"connection_id\":"+c.getClass().getMethod("getId").invoke(c)+"}").getBytes("UTF-8"));
 for(String phase:a[5].split(",")){optimized=phase.equals("sp");for(int i=0;i<warm+measure;i++){if(Boolean.getBoolean("snb.gate"))in=all.getJSONObject(i);Map<String,Long>before=status(c);hit=false;JSONObject marker=new JSONObject();marker.put("phase",phase);marker.put("iteration",i);marker.put("start_wall_ms",System.currentTimeMillis());Files.write(guard.resolve("request-active.json"),marker.toJSONString().getBytes("UTF-8"));long start=System.nanoTime(),cpustart=cpu.getCurrentThreadCpuTime();JSONObject result=SnbSetSql.request(c,in);double ms=(System.nanoTime()-start)/1e6,cpums=(cpu.getCurrentThreadCpuTime()-cpustart)/1e6;Files.deleteIfExists(guard.resolve("request-active.json"));Map<String,Long>after=status(c);JSONObject row=new JSONObject();row.put("query",SnbSetSql.query);row.put("phase",phase);row.put("warmup",i<warm);row.put("iteration",i);row.put("ms",ms);row.put("thread_cpu_ms",cpums);row.put("questions",after.get("Questions")-before.get("Questions")-1);row.put("source_calls",SnbSetSql.calls);Map<String,Long>d=new TreeMap<>();for(String k:after.keySet())d.put(k,after.get(k)-before.get(k));row.put("status_delta",d);row.put("sp_enabled_at_end",hit);row.put("result",result);boolean ok=JSON.parseObject(result.toJSONString()).equals(in.getJSONObject("expected"));row.put("oracle_ok",ok);Files.write(out.resolve("rows.jsonl"),(row.toJSONString()+"\n").getBytes("UTF-8"),StandardOpenOption.CREATE,StandardOpenOption.APPEND);if(!optimized&&row.getLongValue("questions")!=SnbSetSql.calls)throw new IllegalStateException("Independent source/server command count mismatch");if(!ok||(optimized&&!hit)||(optimized&&d.get("Com_call_procedure")<1))throw new IllegalStateException("Oracle/SP activation failed "+row);}}
 }Files.write(out.resolve("completed.json"),"{\"complete\":true}".getBytes("UTF-8"));}
 public static void main(String[]a){try{execute(a);System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
